@st.cache_resource(show_spinner=False)
def _i18n_tables() -> dict:
    import zlib as _zl
    rows = _zl.decompress(base64.b64decode("".join(_I18N_Z))).decode("utf-8").split("\n")
    out = {}
    for i_, lg in enumerate(("ca", "en")):
        m = {}
        for r_ in rows:
            es_, ca_, en_ = r_.split("\t")
            t_ = (ca_, en_)[i_]
            if t_ and t_ != es_:
                m[es_] = t_
        def _rx(keys):
            keys = sorted(keys, key=len, reverse=True)
            pat = "|".join((r"(?<!\w)" if re.match(r"\w", k_) else "") + re.escape(k_)
                           + (r"(?!\w)" if re.search(r"\w$", k_) else "") for k_ in keys)
            return re.compile(pat) if pat else re.compile(r"(?!x)x")
        # Frases que incluyen etiquetas HTML (se aplican sobre el texto entero) y el resto (solo fuera de las etiquetas,
        # para no tocar atributos como data-sec="plan" o href="?sec=…")
        out[lg] = (m, _rx([k_ for k_ in m if "<" in k_]), _rx([k_ for k_ in m if "<" not in k_]))
    return out


_TR_CACHE: dict = {}


def tr(text):
    """Traduce un texto de la interfaz al idioma elegido (frases conocidas; el resto queda igual)."""
    # El idioma se lee de la sesión (no de una variable global): las funciones envueltas de Streamlit se instalan una
    # sola vez por proceso y deben servir a todas las sesiones y recargas.
    lang = st.session_state.get("sb_lang", "ca")
    if lang not in ("ca", "en") or not isinstance(text, str) or not text:
        return text
    ck = (lang, text)
    hit = _TR_CACHE.get(ck)
    if hit is not None:
        return hit
    m, rx_tag, rx = _i18n_tables()[lang]
    if "<style" in text or "<script" in text:
        # CSS y scripts no se tocan: solo el texto que hay fuera de esos bloques
        parts = re.split(r"(<style.*?</style>|<script.*?</script>)", text, flags=re.S)
        res = "".join(p_ if p_.startswith(("<style", "<script")) else tr(p_) for p_ in parts)
        _TR_CACHE[ck] = res
        return res
    if "<" in text:
        res = rx_tag.sub(lambda mo: "\x02" + m.get(mo.group(0), mo.group(0)) + "\x03", text)
        parts = re.split(r"(<[^>]*>|\x02.*?\x03)", res, flags=re.S)
        res = "".join(p_ if (p_.startswith("<") or p_.startswith("\x02")) else
                      rx.sub(lambda mo: m.get(mo.group(0), mo.group(0)), p_) for p_ in parts)
        res = res.replace("\x02", "").replace("\x03", "")
    else:
        res = rx.sub(lambda mo: m.get(mo.group(0), mo.group(0)), text)
    # la «y» entre palabras (frases montadas con variables): i / and
    res = re.sub(r"(?<=[\w)>]) y (?=[\w(<])", " i " if lang == "ca" else " and ", res)
    if len(_TR_CACHE) < 20000:
        _TR_CACHE[ck] = res
    return res


def _tr_fig(fig):
    """Traduce títulos, ejes, leyenda, anotaciones y trazas de una figura de Plotly."""
    try:
        lay = fig.layout
        if lay.title and lay.title.text:
            lay.title.text = tr(lay.title.text)
        for k_ in list(lay.to_plotly_json().keys()):
            if k_.startswith(("xaxis", "yaxis")):
                ax = lay[k_]
                if ax.title and ax.title.text:
                    ax.title.text = tr(ax.title.text)
                if ax.ticktext:
                    ax.ticktext = [tr(str(t_)) for t_ in ax.ticktext]
        if lay.legend and lay.legend.title and lay.legend.title.text:
            lay.legend.title.text = tr(lay.legend.title.text)
        if lay.annotations:
            for a_ in lay.annotations:
                if a_.text:
                    a_.text = tr(a_.text)
        for t_ in fig.data:
            if getattr(t_, "name", None):
                t_.name = tr(t_.name)
            if getattr(t_, "hovertemplate", None):
                t_.hovertemplate = tr(t_.hovertemplate)
            tx = getattr(t_, "text", None)
            if isinstance(tx, str):
                t_.text = tr(tx)
            elif tx is not None and len(tx) and isinstance(tx[0], str):
                t_.text = [tr(x_) for x_ in tx]
            if getattr(t_, "x", None) is not None and len(t_.x) and isinstance(t_.x[0], str) and getattr(t_, "type", "") == "bar":
                t_.x = [tr(x_) for x_ in t_.x]
    except Exception:  # noqa: BLE001
        pass
    return fig


_I18N_NAMES = ["markdown", "caption", "title", "header", "subheader", "text", "info", "warning", "error", "success", "html",
               "expander", "popover", "button", "download_button", "link_button", "toggle", "checkbox", "number_input",
               "text_input", "text_area", "date_input", "time_input", "slider", "metric", "form_submit_button", "radio",
               "selectbox", "multiselect", "segmented_control", "pills", "select_slider", "spinner"]
_I18N_OPTS = {"radio", "selectbox", "multiselect", "segmented_control", "pills", "select_slider"}


def _install_i18n():
    """Envuelve las funciones de Streamlit que pintan texto para traducirlo al vuelo.
    Se reinstala en cada ejecución a partir de las funciones ORIGINALES de Streamlit (las de sus clases base), para que
    al actualizar la app en Streamlit Cloud, que reutiliza el mismo proceso, no queden envolturas de una versión anterior."""
    from streamlit.delta_generator import DeltaGenerator as _DG

    def original(name):
        for base in _DG.__mro__[1:]:
            if name in base.__dict__:
                return base.__dict__[name]
        return None

    def wrap(name):
        orig = original(name)
        if orig is None:
            return

        def f(self, *a, **k):
            if a and isinstance(a[0], str):
                a = (tr(a[0]),) + a[1:]
            for kk in ("label", "body", "help", "placeholder", "text"):
                if isinstance(k.get(kk), str):
                    k[kk] = tr(k[kk])
            if name in _I18N_OPTS:
                ff = k.get("format_func")
                k["format_func"] = (lambda v, _f=ff: tr(str(_f(v)))) if ff else (lambda v: tr(str(v)))
            return orig(self, *a, **k)
        f.__name__ = name
        setattr(_DG, name, f)

    for n_ in _I18N_NAMES:
        wrap(n_)
    _w = original("write")
    if _w is not None:
        def _write(self, *a, **k):
            return _w(self, *[tr(x_) if isinstance(x_, str) else x_ for x_ in a], **k)
        _DG.write = _write
    _tb = original("tabs")
    if _tb is not None:
        def _tabs(self, tabs, *a, **k):
            return _tb(self, [tr(t_) for t_ in tabs], *a, **k)
        _DG.tabs = _tabs
    _pc = original("plotly_chart")
    if _pc is not None:
        def _plotly(self, fig, *a, **k):
            return _pc(self, _tr_fig(fig), *a, **k)
        _DG.plotly_chart = _plotly
    # Las funciones st.* son métodos ya enlazados al contenedor principal: se vuelven a enlazar con las versiones nuevas
    main_ = getattr(st.markdown, "__self__", None)
    if main_ is not None:
        for n_ in _I18N_NAMES + ["write", "tabs", "plotly_chart"]:
            if n_ in _DG.__dict__:
                setattr(st, n_, _DG.__dict__[n_].__get__(main_, _DG))


_install_i18n()

